CREATE TABLE IF NOT EXISTS purchase_requisitions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id TEXT NOT NULL UNIQUE,company_id UUID NOT NULL REFERENCES companies(id),requester_user_id UUID NOT NULL REFERENCES users(id),department_id UUID REFERENCES departments(id),branch_id UUID REFERENCES branches(id),title TEXT NOT NULL,justification TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'normal',required_date DATE,destination_type TEXT NOT NULL,destination_business_id TEXT,destination_name TEXT NOT NULL,estimated_total NUMERIC(14,2) NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','reviewed','approved','returned','rejected','ordered','partially_ordered','completed')),portal_request_id UUID REFERENCES portal_requests(id),reviewed_by UUID REFERENCES users(id),reviewed_at TIMESTAMPTZ,review_notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_requisition_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),requisition_id UUID NOT NULL REFERENCES purchase_requisitions(id) ON DELETE CASCADE,item_type TEXT NOT NULL,item_description TEXT NOT NULL,quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),unit TEXT NOT NULL DEFAULT 'unit',estimated_unit_cost NUMERIC(14,2) NOT NULL DEFAULT 0,quantity_ordered NUMERIC(14,3) NOT NULL DEFAULT 0,specification TEXT);
ALTER TABLE purchase_orders ALTER COLUMN warehouse_id DROP NOT NULL;
ALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS requisition_id UUID REFERENCES purchase_requisitions(id),ADD COLUMN IF NOT EXISTS purchase_type TEXT NOT NULL DEFAULT 'INVENTORY',ADD COLUMN IF NOT EXISTS destination_type TEXT,ADD COLUMN IF NOT EXISTS destination_business_id TEXT,ADD COLUMN IF NOT EXISTS destination_name TEXT,ADD COLUMN IF NOT EXISTS emergency_purchase BOOLEAN NOT NULL DEFAULT false,ADD COLUMN IF NOT EXISTS emergency_reason TEXT;
ALTER TABLE purchase_order_items ALTER COLUMN product_id DROP NOT NULL;
ALTER TABLE purchase_order_items ADD COLUMN IF NOT EXISTS requisition_item_id UUID REFERENCES purchase_requisition_items(id),ADD COLUMN IF NOT EXISTS item_description TEXT,ADD COLUMN IF NOT EXISTS item_type TEXT NOT NULL DEFAULT 'INVENTORY',ADD COLUMN IF NOT EXISTS unit TEXT NOT NULL DEFAULT 'unit',ADD COLUMN IF NOT EXISTS receiving_action TEXT NOT NULL DEFAULT 'STOCK' CHECK(receiving_action IN('STOCK','ASSET','CONSUMABLE','DIRECT_USE','SERVICE'));
ALTER TABLE purchase_order_receipts ADD COLUMN IF NOT EXISTS receipt_type TEXT NOT NULL DEFAULT 'GRN',ADD COLUMN IF NOT EXISTS destination_type TEXT,ADD COLUMN IF NOT EXISTS destination_business_id TEXT,ADD COLUMN IF NOT EXISTS destination_name TEXT,ADD COLUMN IF NOT EXISTS condition_status TEXT,ADD COLUMN IF NOT EXISTS accepted_by_name TEXT,ADD COLUMN IF NOT EXISTS inspection_notes TEXT;
ALTER TABLE purchase_order_receipt_items ADD COLUMN IF NOT EXISTS serial_numbers JSONB NOT NULL DEFAULT '[]',ADD COLUMN IF NOT EXISTS warranty_until DATE,ADD COLUMN IF NOT EXISTS condition_status TEXT,ADD COLUMN IF NOT EXISTS remarks TEXT;
CREATE TABLE IF NOT EXISTS procured_assets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id TEXT NOT NULL UNIQUE,company_id UUID NOT NULL REFERENCES companies(id),po_item_id UUID NOT NULL REFERENCES purchase_order_items(id),receipt_id UUID NOT NULL REFERENCES purchase_order_receipts(id),asset_type TEXT NOT NULL,name TEXT NOT NULL,serial_number TEXT,destination_type TEXT,destination_business_id TEXT,destination_name TEXT,condition_status TEXT,warranty_until DATE,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO numbering_sequences(module_code,prefix_template,padding_length,reset_policy) VALUES('PURCHASE_REQUISITION','PRQ-{YYYYMMDD}-',6,'daily'),('PROCURED_ASSET','AST-{YYYYMMDD}-',6,'daily') ON CONFLICT(module_code) DO NOTHING;
INSERT INTO workflow_definitions(company_id,workflow_key,display_name,require_attachment,approval_steps) SELECT id,'purchase_requisition','Purchase requisition',false,'[{"name":"Department review","department":"operations","permission":"USER_MANAGEMENT_APPROVE","required":true,"allowReject":true},{"name":"Procurement authorization","department":"procurement","permission":"INVENTORY_APPROVE","required":true,"allowReject":true}]'::jsonb FROM companies ON CONFLICT(company_id,workflow_key) DO NOTHING;
